mapper.select:
SELECT *
FROM user_access_review
WHERE cmdb_id = #{cmdbId}
    AND it_code_of_user = #{itCode}
    AND user_id = #{userId}
    AND system_role = #{systemRole}
    AND role_description = #{roleDescription}
    AND leit_system_id = #{leitSystemId}
    AND delete_flag = false
LIMIT 1

SELECT
    sub.label AS label,
    sub.value AS "value"
FROM
    (SELECT DISTINCT app.application_name AS label, app.cmdb_id as  "value"
    FROM its_application_data app
    INNER JOIN user_access_review uar on app.cmdb_id = uar.cmdb_id
    WHERE uar.delete_flag = false

            and uar.line_manager_review_status =#{lineManagerReviewStatus}


            and uar.it_code_of_user =#{itCodeOfUser}


            and uar.line_managers_review_decision =#{lineManagersReviewDecision}

    order by "value"
    ) AS sub

